export default function JohnBosco({
  p,
  detail,
}: PortraitProps) {
  return (
    <>
      <g transform={ART_TRANSFORM}>
        <rect
          x="0"
          y="0"
          width="1086"
          height="1448"
          fill={PAPER}
          pointerEvents="none"
        />

        {/* Sky, grounds, trees, paths, and remaining scene base. */}
        <g {...p('background')} stroke="none">
          <rect x="0" y="0" width="1086" height="1448" />
        </g>

        {/* Cloud banks on the left and right. */}
        <g {...p('cloud')} stroke="none">
          <path d={CLOUD_MASK} fillRule="evenodd" />
        </g>

        {/* Circular halo behind St. John Bosco. */}
        <g {...p('halo')} stroke="none">
          <path d={HALO_MASK} fillRule="evenodd" />
        </g>

        {/* Church, school buildings, and selected background architecture. */}
        <g {...p('symbol')} stroke="none">
          <path d={SYMBOL_MASK} fillRule="evenodd" />
        </g>

        {/* St. John Bosco's cassock and main garment. */}
        <g {...p('robe')} stroke="none">
          <path d={ROBE_MASK} fillRule="evenodd" />
        </g>

        {/* Boys' jackets/clothing and Bosco's neck bow/collar accents. */}
        <g {...p('mantle')} stroke="none">
          <path d={MANTLE_MASK} fillRule="evenodd" />
        </g>

        {/* Hair for Bosco and both boys. */}
        <g {...p('hair')} stroke="none">
          <path d={HAIR_MASK} fillRule="evenodd" />
        </g>

        {/* The Young Man's Guide, football, cap, and bow-tie details. */}
        <g {...p('accent')} stroke="none">
          <path d={ACCENT_MASK} fillRule="evenodd" />
        </g>

        {/* Faces, necks, and all visible hands. */}
        <g {...p('skin')} stroke="none">
          <path d={SKIN_MASK} fillRule="evenodd" />
        </g>

        {/* Exact traced black line art from the supplied John Bosco image.
            Keep this last and non-interactive. */}
        <path
          {...detail}
          {...ink}
          d={JOHN_BOSCO_LINE_ART}
          fill={STROKE}
          stroke="none"
          fillRule="evenodd"
          pointerEvents="none"
          shapeRendering="geometricPrecision"
        />
      </g>
    </>
  );
}